private function classify(MessageMedia $media, string $ocrText, \Illuminate\Support\Collection $activeTypes, array $owed = []): ?array
{
    $parsed = $this->read([$media], [$ocrText], $activeTypes, $owed)[0] ?? null;

    return $parsed === null ? null : $this->interpret($media, $ocrText, $activeTypes, $parsed);
}

private function fillMissingFields(MessageMedia $media, string $ocrText, DocumentType $type, array $fields, ?string $effort = null): array
{
    $all = $type->allFields();

    if ($all === []) {
        return $fields;
    }

    try {
        $response = $this->ai->chat(new AiRequest(
            purpose: 'document',
            label: 'document',
            system: "This document is: {$type->label} - {$type->description_for_ai}\n\n"
                .'Extract these fields: '.implode(', ', $all).'. Copy every number digit by digit exactly as printed '
                .'(check it against the OCR text), converting Arabic-Indic digits to 0-9; an amount is the one the field '
                .'description names (e.g. net = صافي), without currency or thousands separators. Dates as YYYY-MM-DD. '
                .'Today is '.now()->toDateString().' - resolve relative periods against it. '
                .'A date printed with a typo (a 5-digit year like 20246, a missing digit) is read as the date it plainly means from the '
                .'other dates on the document and today - an issue date can never be before the hire date on the same paper. '
                .'The person\'s name is the person the document is about (the employee, the pensioner), never a manager or signer in the letterhead. '
                .'Use an empty string only if the value is truly not on the document.'."\n\n"
                ."OCR text:\n{$ocrText}",
            contents: [
                ['role' => 'user', 'parts' => [
                    ['type' => 'inline_media', 'mime' => $media->mime, 'base64' => base64_encode(Storage::disk($media->disk)->get($media->path))],
                ]],
            ],
            toolMode: 'none',
            temperature: 0.1,
            maxOutputTokens: 1024,
            thinkingBudget: 0,
            thinkingLevel: $effort,
            responseSchema: [
                'type' => 'object',
                'properties' => collect($all)->mapWithKeys(fn ($key) => [$key => DocumentFields::schema($key)])->all(),
                'required' => array_values((array) ($type->extraction_fields ?? [])),
            ],
        ));
    } catch (AiProviderException $e) {
        Log::warning('Document field extraction failed', ['media_id' => $media->id, 'error' => $e->getMessage()]);

        return $fields;
    }

    $focused = json_decode(implode('', $response->textParts), true) ?? [];

    foreach ($this->withoutEmptyValues(array_intersect_key(is_array($focused) ? $focused : [], array_flip($all))) as $key => $value) {
        $fields[$key] = $value;
    }

    return $fields;
}

public function execute(array $args, ToolContext $ctx): ToolResult
{
    $media = MessageMedia::with('message')->find($args['media_id']);

    if (! $media || $media->message?->whatsapp_conversation_id !== $ctx->conversationId) {
        return ToolResult::error('MEDIA_NOT_FOUND', 'No such image in this conversation. If this message has no attachment, '
            .'work out what "دي" means from the quoted message and the recent conversation - do not tell the customer an image failed.');
    }

    if ($media->media_type !== 'image' && $media->media_type !== 'sticker') {
        return ToolResult::error('NOT_AN_IMAGE');
    }

    $catalogList = Machine::query()->where('is_active', true)->with('brand')->get()
        ->map(fn (Machine $m) => "{$m->id}: ".trim(($m->brand?->name ?? '').' '.$m->name))
        ->implode("\n");

    // "Qg SRK 250" was the photo's caption and the bike's real model;
    // it was matched to our Rk200 R and the customer was told so three
    // times. What the customer wrote with the photo is evidence too.
    $caption = trim((string) ($media->message?->text ?? ''));

    try {
        $response = $this->provider->chat(new AiRequest(
            purpose: 'image',
            label: 'image',
            system: "You identify a motorcycle photo against this catalog (id: name), one per line:\n{$catalogList}\n\n"
                .'Identify the MAIN motorcycle only: the one in the centre / in focus / taking most of the frame. '
                .'Set vehicle_count to how many motorcycles or scooters are visible (even partly). '
                .'Report how you know: identified_by = "visible_name_or_logo" only if the model name or brand is actually readable on the MAIN bike itself - '
                .'a logo on a neighbouring bike says nothing about the main one; '
                .'"shape_only" if you are judging by shape/colour/design; "not_a_motorcycle" if the image is not a motorcycle. '
                .'Many models share a body - by shape alone, list every plausible candidate with honest (lower) confidence. '
                .'Also say what the bike really is: observed.model = the exact make and model you recognise (from a readable name, the caption, '
                .'or its distinctive design - e.g. "QJ Motor SRK 250"), even when it is not in the catalog; empty if you cannot tell. '
                .'in_catalog = false when that model is not one of the catalog lines (a sibling model of the same brand is NOT the same model - '
                .'SRK 250 is not Rk200 R); then candidates are only look-alike alternatives with low confidence.'
                .($caption !== '' ? "\n\nThe customer wrote with the photo: \"{$caption}\"" : ''),
            contents: [
                ['role' => 'user', 'parts' => [
                    ['type' => 'inline_media', 'mime' => $media->mime, 'base64' => base64_encode(Storage::disk($media->disk)->get($media->path))],
                ]],
            ],
            toolMode: 'none',
            temperature: 0.1,
            responseSchema: [
                'type' => 'object',
                'properties' => [
                    'candidates' => [
                        'type' => 'array',
                        'items' => [
                            'type' => 'object',
                            'properties' => [
                                'motorcycle_id' => ['type' => 'integer'],
                                'confidence' => ['type' => 'number'],
                            ],
                        ],
                    ],
                    'identified_by' => ['type' => 'string', 'enum' => ['visible_name_or_logo', 'shape_only', 'not_a_motorcycle']],
                    'in_catalog' => ['type' => 'boolean'],
                    'vehicle_count' => ['type' => 'integer'],
                    'observed' => [
                        'type' => 'object',
                        'properties' => [
                            'brand' => ['type' => 'string'],
                            'model' => ['type' => 'string'],
                            'style' => ['type' => 'string'],
                        ],
                    ],
                ],
            ],
        ));
    } catch (AiProviderException) {
        return ToolResult::error('VISION_UNAVAILABLE');
    }

    $parsed = json_decode(implode('', $response->textParts), true) ?? [];
    $activeIds = Machine::where('is_active', true)->pluck('id')->all();

    $candidates = collect($parsed['candidates'] ?? [])
        ->filter(fn ($c) => in_array((int) ($c['motorcycle_id'] ?? 0), $activeIds, true))
        ->map(fn ($c) => [
            'motorcycle_id' => (int) $c['motorcycle_id'],
            'name' => Machine::find($c['motorcycle_id'])->name,
            'confidence' => (float) ($c['confidence'] ?? 0),
        ])
        ->sortByDesc('confidence')
        ->values();

    $identifiedBy = $parsed['identified_by'] ?? 'shape_only';

    if ($identifiedBy === 'not_a_motorcycle') {
        $candidates = collect();
    }

    $band = $this->band($candidates->first()['confidence'] ?? 0);

    // The official H250 photo came back as "VLM 200, 0.95, match": a
    // confidence the model gives itself for a front shot with no name on
    // it. An exact model needs visible evidence; by shape alone the most
    // this can be is "similar", and the agent must say so.
    if ($band === 'match' && $identifiedBy !== 'visible_name_or_logo') {
        $band = 'similar';
    }

    // Live: a photo of a row of scooters came back "vigorey, logo, match"
    // - the logo was on the scooter beside the one the customer meant
    // (a Demora). With several bikes in frame the photo cannot pin one
    // model down; the agent has to ask which one.
    $vehicleCount = (int) ($parsed['vehicle_count'] ?? 1);

    if ($band === 'match' && $vehicleCount > 1) {
        $band = 'similar';
    }

    // The model it recognised is not one we carry: never "this is our X".
    $observedModel = trim((string) ($parsed['observed']['model'] ?? ''));

    if (($parsed['in_catalog'] ?? true) === false && $observedModel !== '' && $identifiedBy !== 'not_a_motorcycle') {
        $band = 'not_in_catalog';
        $candidates = $candidates->map(fn ($c) => ['confidence' => min($c['confidence'], 0.4)] + $c);
    }

    $result = [
        'band' => $band,
        'identified_by' => $identifiedBy,
        'candidates' => $candidates->all(),
        'observed' => $parsed['observed'] ?? [],
    ] + ($vehicleCount > 1 ? ['vehicle_count' => $vehicleCount] : []);

    // Simulator 691: an SRK 250 photo, then "ايه المتاح؟" got 150cc
    // bikes. What the photo shows is what he is after.
    if ($band === 'not_in_catalog' && ($cc = CustomerInterest::ccIn($observedModel)) !== null) {
        $kind = str_contains(mb_strtolower((string) ($parsed['observed']['style'] ?? '')), 'scooter') ? 'scooter' : 'motorcycle';
        $result['similar_available'] = app(\App\Domain\Catalog\CatalogService::class)->similar($cc, $kind, null, 5);
        $result['similar_cc'] = $cc;
    }

    $media->update(['analysis' => $result]);

    return ToolResult::ok($result);
}

private function prompt(Machine $machine, array $specs): string
{
    $asked = implode("\n", array_map(fn ($s) => "- {$s}", $specs));

    return <<<PROMPT
    Use Google Search to find the manufacturer specifications of this exact motorcycle:
    Brand: {$machine->brand->name}
    Model: {$machine->name}
    Engine displacement: {$machine->cc} cc
    Model year: {$machine->model_year}

    Specs requested (answer each by the same name, as asked):
    {$asked}

    Rules:
    - Only use sources about this exact brand and model, with the same engine displacement and the same model year (or a source that explicitly covers that year).
    - A different year, a different engine size, or a similarly named model does NOT count - then that spec is not found.
    - Never estimate, round or infer a value. Leave out any spec you could not confirm.
    - Write each value in Egyptian Arabic with its unit (e.g. "11.5 لتر", "90/90-18").

    Reply with ONLY this JSON, no other text:
    {"found": true|false, "matched_model": "...", "matched_cc": 0, "matched_year": 0, "specs": [{"name": "...", "value": "..."}]}
    PROMPT;
}

public function split(array $stored, array $customerMessages, string $which = 'home'): array
{
    $stored = array_filter($stored, fn ($v) => trim((string) $v) !== '');

    if ($stored === [] && $customerMessages === []) {
        return [];
    }

    try {
        $response = $this->ai->chat(new AiRequest(
            purpose: 'address',
            label: 'address',
            system: 'You split an Egyptian address into the fields of a finance application form. '
                .'Use only what the customer wrote; never invent a number, street or landmark. '
                .'governorate = the Egyptian governorate in Arabic (القاهرة، الجيزة، القليوبية ...) - infer it from a well known city/district '
                .'(مدينة بدر، مدينة نصر، العبور، الشروق، التجمع → القاهرة؛ الهرم، فيصل، ٦ أكتوبر → الجيزة؛ شبرا الخيمة، الخصوص → القليوبية) when he did not say it. '
                .'area = the district / city / neighbourhood (e.g. "مدينة بدر - الحي التاني"). street = the street name. '
                .'branch_street = the street it branches from ("متفرع من ..."). building_number = the building/house number (عمارة/عقار/بيت). '
                .'floor = the floor only (دور). apartment = the apartment number only (شقة) - "شقة 41" is an apartment, never a floor. '
                .'landmark = the nearby known place (جنب/أمام/خلف ...). Fix obvious typos of well known places only (الجمعه الروسيه → الجامعة الروسية). '
                .'Leave a field empty when it is not given. '
                // Request 4395: the work address was split from a message
                // that held the home address first - it came back as the home.
                .($which === 'work'
                    ? 'This is his WORK address (where he works). The messages may also hold his home address - ignore it. '
                    : 'This is his HOME address (where he lives). The messages may also hold his work address - ignore it. ')
                .'saved_fields is what he gave for this address: split saved_fields.address / work_address, and use the messages only to read it right.',
            contents: [[
                'role' => 'user',
                'parts' => [['type' => 'text', 'text' => json_encode([
                    'saved_fields' => $stored,
                    'customer_messages' => array_values($customerMessages),
                ], JSON_UNESCAPED_UNICODE)]],
            ]],
            toolMode: 'none',
            temperature: 0.0,
            maxOutputTokens: 600,
            thinkingBudget: 0,
            // Runs inside the submission transaction - never hold it long.
            timeoutSeconds: 25,
            responseSchema: [
                'type' => 'object',
                'properties' => collect(self::PARTS)->mapWithKeys(fn ($p) => [$p => ['type' => 'string']])->all(),
            ],
        ));
    } catch (AiProviderException|\Throwable $e) {
        Log::warning('AddressSplitter failed', ['error' => $e->getMessage()]);

        return [];
    }

    $parsed = json_decode(implode('', $response->textParts), true);

    if (! is_array($parsed)) {
        return [];
    }

    return array_filter(
        array_map(fn ($v) => is_scalar($v) ? trim((string) $v) : '', array_intersect_key($parsed, array_flip(self::PARTS))),
        fn ($v) => $v !== '' && ! in_array(mb_strtolower($v), ['null', 'none', 'n/a', '-', 'غير محدد'], true)
    );
}

public function handle(AiProvider $ai): void
{
    $conversation = WhatsappConversation::find($this->conversationId);

    if (! $conversation) {
        return;
    }

    $since = $conversation->summary_until_message_id ?? 0;

    $messages = WhatsappMessage::where('whatsapp_conversation_id', $conversation->id)
        ->where('id', '>', $since)
        ->where('id', '<', $this->upToMessageId)
        ->orderBy('id')
        ->get();

    if ($messages->isEmpty()) {
        return;
    }

    $transcript = $messages
        ->map(fn (WhatsappMessage $m) => ($m->sender_type === 'customer' ? 'العميل' : 'الرد')
            .': '.($m->text ?? $m->transcript ?? '[وسائط]'))
        ->implode("\n");

    $list = ['type' => 'array', 'items' => ['type' => 'string']];

    try {
        $response = $ai->chat(new AiRequest(
            purpose: \App\Services\GeminiKeyManager::isTestPhone($conversation->phone) ? 'simulator' : 'summary',
            label: 'summary',
            // CTX-010: free prose mixed what he said with chat filler; the
            // model could not tell a decision from a passing remark.
            system: 'اكتب ملخص المحادثة دي بالعربي في 3 قوايم، كل بند سطر قصير محايد:'."\n"
                .'facts: حقايق عن العميل قالها أو اتأكدت (شغله، سنه، منطقته، الموتوسيكل اللي عايزه، ميزانيته).'."\n"
                .'decisions: اللي اتفق عليه أو اختاره (موديل، مدة، مقدم، فتح طلب، طلب يكلم حد).'."\n"
                .'still_open: اللي لسه مستني رد أو ورق أو سؤال ماتجاوبش.'."\n"
                .'اكتب الملخص كله من جديد من الملخص السابق والرسائل الجديدة؛ الجديد يغلب القديم، وشيل اللي اتقفل من still_open. '
                .'من غير أي بيانات حساسة زي أرقام قومية أو بيانات مستندات، ومن غير أرقام أسعار أو أقساط (دي بتتجاب من الأدوات).',
            contents: [
                ['role' => 'user', 'parts' => [[
                    'type' => 'text',
                    'text' => 'الملخص السابق:'."\n".($conversation->summary ?: '(لا يوجد)')."\n\n"
                        .'الرسائل الجديدة:'."\n".$transcript,
                ]]],
            ],
            toolMode: 'none',
            temperature: 0.2,
            responseSchema: ['type' => 'object', 'properties' => ['facts' => $list, 'decisions' => $list, 'still_open' => $list]],
        ));
    } catch (AiProviderException) {
        return;
    }

    $structured = self::decode(implode('', $response->textParts));

    if ($structured === null || array_merge(...array_values($structured)) === []) {
        return;
    }

    $conversation->update([
        'summary' => json_encode($structured, JSON_UNESCAPED_UNICODE),
        'summary_until_message_id' => $messages->last()->id,
        'summary_updated_at' => now(),
    ]);
}

private function ask(WhatsappConversation $conversation, ?int $targetMessageId, string $ownerText, ?string $failedCheck = null): array
{
    $transcript = $this->context->transcript($conversation->id, $targetMessageId);
    $prompt = "# المحادثة\n{$transcript}\n\n# كلام صاحب الشغل\n{$ownerText}";

    if ($failedCheck) {
        $prompt .= "\n\n# محاولتك الأولى ما نجحتش\nصلّح العمليات (ابعت كل القيم كاملة) أو صياغة الدرس عشان يبقى أوضح للبوت، أو اسأل صاحب الشغل لو المشكلة مش في الصياغة.\n{$failedCheck}";
    }

    $system = trim((string) file_get_contents(resource_path('agent/instructions/coach.md')))
        ."\n\n".$this->context->knowledge($ownerText."\n".$transcript);

    // Live: "البوت يسأل" and then blank spaces until MAX_TOKENS, twice in
    // a row - Gemini's schema-constrained output can get stuck repeating
    // whitespace. Each retry changes what drives the loop: a higher
    // temperature, then free JSON with no schema at all.
    // The second try leaves the schema: live, the fallback model looped
    // on it to MAX_TOKENS twice in a row (sessions 44/45, 3 minutes).
    $attempts = [
        ['temperature' => 0.2, 'schema' => true],
        ['temperature' => 0.4, 'schema' => false],
        ['temperature' => 0.7, 'schema' => true],
    ];
    $failure = null;

    foreach ($attempts as $attempt) {
        $request = new AiRequest(
            purpose: 'teaching',
            label: 'teaching_coach',
            system: $system.($attempt['schema'] ? '' : "\n\n## شكل الرد\nرد بـ JSON بس (من غير أي كلام قبله أو بعده) بالمفاتيح دي بالظبط:\n"
                .json_encode($this->schema(), JSON_UNESCAPED_UNICODE)),
            contents: [['role' => 'user', 'parts' => [['type' => 'text', 'text' => $prompt]]]],
            toolMode: 'none',
            temperature: $attempt['temperature'],
            // Enough for a long plan; a stuck reply fails fast instead of
            // making the owner wait for 16k tokens of spaces.
            maxOutputTokens: 8192,
            // gemini-3.5-flash answers a correction in ~10-30s. Overloaded,
            // it held the connection 2 minutes before the fallback got a
            // turn - same model and thinking, just no waiting on a dead line.
            timeoutSeconds: 45,
            responseSchema: $attempt['schema'] ? $this->schema() : null,
            thinkingLevel: config('agent.teaching.coach_thinking') ?: 'low',
        );

        try {
            $response = $this->withCoachModel(fn () => $this->ai->chat($request));
        } catch (\App\Agent\Providers\AiProviderException $e) {
            $failure = 'المدرّب مش متاح دلوقتي ('.$e->getMessage().')';

            continue;
        }

        $plan = $this->parsePlan(implode('', $response->textParts));

        if ($plan !== null) {
            return $plan;
        }

        $failure = "رد المدرّب مش مفهوم ({$response->finishReason})";
        \Illuminate\Support\Facades\Log::warning('Teaching coach reply unusable, retrying', [
            'finish_reason' => $response->finishReason, 'schema' => $attempt['schema'],
            'head' => mb_substr(implode('', $response->textParts), 0, 200),
        ]);
    }

    throw new \RuntimeException(($failure ?? 'رد المدرّب مش مفهوم').' - جرّب تبعت التصحيح تاني.');
}

private function keepGoingReply(WhatsappConversation $conversation): string
{
    $application = $conversation->customer_id
        ? Application::where('customer_id', $conversation->customer_id)->whereIn('status', Application::ACTIVE_STATUSES)->latest('id')->first()
        : null;

    try {
        $step = $application ? (app(\App\Domain\Applications\SnapshotService::class)->for($application)['next_step'] ?? null) : null;
    } catch (\Throwable) {
        $step = null;
    }

    if (in_array($step['type'] ?? null, ['field', 'document'], true) && filled($step['label'] ?? null)) {
        return "تمام يا باشا، عشان نكمّل طلبك ابعتلي {$step['label']}";
    }

    // Conversation 857: "خلاص خلينا في الهوجن L250 على سنتين" with
    // everything in got "ممكن توضحلي تقصد إيه؟" - he was perfectly clear.
    if (($step['type'] ?? null) === 'submit') {
        return 'تمام يا باشا، كده طلبك جاهز. أقدّمهولك دلوقتي؟';
    }

    if ($application) {
        return 'تمام يا باشا، معاك. نكمّل طلبك؟';
    }

    return 'معلش يا باشا، ممكن توضحلي تقصد إيه بالظبط عشان أرد عليك صح؟';
}

private function fallback(WhatsappConversation $conversation, AiTrace $trace, array $guardEvents, string $reason): array
{
    $message = config('agent.fallback.message');

    if ($message === null) {
        throw new \RuntimeException("AgentRunner: fallback triggered ({$reason}) but agent.fallback.message is not configured (DEC-13).");
    }

    $failures = $this->recordFailure($conversation);
    $this->finishTrace($trace, 'fallback', $guardEvents, null, $reason);

    $maxFailedTurns = config('agent.handoff.max_failed_turns');

    if ($maxFailedTurns !== null && $failures >= (int) $maxFailedTurns) {
        $this->handoff->handOffForFailures($conversation, $reason);
    }

    return ['messages' => [$message]];
}

public function explanation(float $cap, ?int $customerTypeId): string
{
    // the owner's wording: above the cap, the difference is paid in cash and the rest is financed.
    // The cap figure and his type stay internal (instructions §5, WORK_TYPE_TOLD): the customer
    // hears the reason and his own numbers (cash_due_upfront), not "أقصى تمويل 60,000 لعامل حر".
    return 'على حسب نوع شغلك جهة التمويل بتمول لحد مبلغ معين، والمكنة دي أعلى منه، '
        .'فجزء من تمنها بيتدفع كاش وقت الاستلام مع المصاريف الإدارية، والباقي بيتقسط.';
}

public function execute(array $args, ToolContext $ctx): ToolResult
{
    $application = $ctx->activeApplicationId ? Application::find($ctx->activeApplicationId) : null;

    if (! $application) {
        return ToolResult::error('NO_ACTIVE_APPLICATION');
    }

    try {
        $result = $this->submissions->submit($application, $ctx->turnId, ($args['confirm'] ?? false) === true);
    } catch (SubmissionException $e) {
        return ToolResult::error($e->errorCode, $e->getMessage() !== $e->errorCode ? $e->getMessage() : '');
    }

    if ($result['submitted'] === true) {
        return ToolResult::ok(['submitted' => true, 'reference' => $result['reference']]
            + (($result['resubmitted'] ?? false) ? ['resubmitted' => true] : []));
    }

    // Not submitted is never a success. The summary is sent by Laravel,
    // verbatim from the DB, right after the AI's own message.
    $ctx->outbound->addTrailingMessage($result['review_text']);

    // QA 2026-10-04: the line before the summary said "ناقص الرقم القومي ونوع
    // الشغل" while the summary showed them recorded (✓), and an "اه" after
    // it got "عايز أقدّم دلوقتي؟" twice more.
    // what the reply around the summary is: the instructions (§٨)
    return ToolResult::error('CUSTOMER_CONFIRMATION_REQUIRED', 'Not submitted yet. The stored summary is sent to him right after your message.');
}

public function execute(array $args, ToolContext $ctx): ToolResult
{
    $customerType = CustomerType::where('key', $args['customer_type'])->where('is_active', true)->first();

    if (! $customerType) {
        return ToolResult::error('UNKNOWN_CUSTOMER_TYPE', "Unknown customer type: {$args['customer_type']}");
    }

    $facts = $this->recordedFacts($ctx);

    foreach ((array) ($args['facts'] ?? []) as $key => $value) {
        $field = RequirementField::where('key', $key)->where('data_type', 'enum')->first();

        if (! $field || ! in_array($value, (array) $field->enum_options, true)) {
            return ToolResult::error('INVALID_ARGUMENTS', "facts.{$key} must be one of: ".implode(', ', (array) $field?->enum_options));
        }

        $facts[$key] = $value;
    }

    $requirements = $this->requirements->requirementsFor($customerType, $facts);

    // QA 2026-10-04: "المطلوب ايه؟" got nine data fields and "مفردات مختومة" -
    // the answer is the papers, by their own names; the data is asked
    // one step at a time once the application is open.
    $papers = collect($requirements['documents'] ?? [])->where('required', true)->pluck('label')->values()->all();

    return ToolResult::ok([
        'documents' => $requirements['documents'] ?? [],
        'papers' => $papers,
        'fields_count' => count($requirements['fields'] ?? []),
        'facts_used' => $facts,
        'conditional' => $this->unresolvedConditional($customerType, $facts),
    ] + array_diff_key($requirements, ['documents' => 1, 'fields' => 1]));
}
